package dev.zomboidmelee.boxing;
import net.minecraft.client.model.*;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.renderer.entity.player.PlayerRenderer;import net.minecraft.client.player.AbstractClientPlayer;import net.minecraft.client.renderer.MultiBufferSource;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
public final class Render20{
 static void frame(PoseStack p,Motion20.Frame f){p.translate(f.x(),f.y(),f.z());p.mulPose(Axis.YP.rotationDegrees((float)f.ry()));p.mulPose(Axis.XP.rotationDegrees((float)f.rx()));p.mulPose(Axis.ZP.rotationDegrees((float)f.rz()));}
 public static void arm(Object r,Object pose,Object buffer,int light,Object player,int side,int kind,int combo,double phase){PoseStack p=(PoseStack)pose;p.pushPose();try{frame(p,Motion20.arm(kind,side,combo,phase));p.translate(side==0?.3125:-.3125,-.125,0);if(side==0)((PlayerRenderer)r).renderRightHand(p,(MultiBufferSource)buffer,light,(AbstractClientPlayer)player);else((PlayerRenderer)r).renderLeftHand(p,(MultiBufferSource)buffer,light,(AbstractClientPlayer)player);}finally{p.popPose();}}
 public static void leg(Object r,Object pose,Object buffers,int light,Object player,double phase){StompMesh21.draw(r,pose,buffers,light,player,phase);}
 public static void pose(Object o,int side,float x,float y,float z){if(!(o instanceof HumanoidModel<?>m))return;ModelPart arm=side==0?m.rightArm:m.leftArm;if(arm!=null){arm.xRot=x;arm.yRot=y;arm.zRot=z;}if(o instanceof PlayerModel<?>p){ModelPart sleeve=side==0?p.rightSleeve:p.leftSleeve;if(sleeve!=null&&arm!=null)sleeve.copyFrom(arm);}}
 public static void body(Object o,int kind,double p,int combo){if(!(o instanceof HumanoidModel<?>m))return;double a=Motion20.strike(kind,p);for(int side=0;side<2;side++){int sign=side==0?1:-1;double active=side==Math.floorMod(combo,2)?a:a*.045;float rx=(float)(-1.06-.65*active),ry=(float)(-sign*(.20-.12*active)),rz=sign*.10f;if(kind==Motion20.HEAVY){ry=(float)(-sign*(.25-.70*active));rz=(float)(sign*(.12+.35*Math.max(0,active)));}else if(kind==Motion20.SHOVE){rx=(float)(-.85-.65*a);ry=-sign*.12f;}else if(kind==Motion20.INTERACT){double reach=Motion20.track(p,new double[]{0,.17,.39,.58,1},new double[]{0,.2,1,.82,0});if(side==0){rx=(float)(-1.06-.6*reach);ry=(float)(-.2+.3*reach);rz=(float)(.1+.15*reach);}}else if(kind==Motion20.SEARCH){double wave=Math.sin(p*Math.PI*2+side*Math.PI);rx=(float)(-.75-.20*wave);ry=-sign*.2f;}pose(o,side,rx,ry,rz);}
  if(m.body!=null){if(kind==Motion20.HEAVY)m.body.yRot+=(float)(.30*a*(combo%2==0?1:-1));if(kind==Motion20.SEARCH)m.body.xRot+=.16f;if(kind==Motion20.STOMP)m.body.xRot+=(float)(.17*Motion20.stamp(p));}
  if(kind==Motion20.STOMP&&m.rightLeg!=null){m.rightLeg.xRot=(float)(-1.25*Motion20.lift(p)+.15*Motion20.stamp(p));m.rightLeg.zRot=.05f;}
 }
}
